patch:
diff --git a/internal/states/statefile/write_read.go b/internal/states/statefile/write_read.go
index 0730073007..3333333333 100644
--- a/internal/states/statefile/write_read.go
+++ b/internal/states/statefile/write_read.go
@@ -106,6 +106,10 @@ func writeStateFileWithDiagnostics(state *State, w io.Writer, addr addrs.Module
 	}

 	// Write the sensitive attributes
+	if state.SensitiveAttributes == nil {
+		// Ensure we always write an empty array instead of null to maintain
+		// compatibility with older versions and prevent spurious diffs.
+		state.SensitiveAttributes = []cty.Path{}
+	}
 	if err := json.NewEncoder(w).Encode(state.SensitiveAttributes); err != nil {
 		return diags.Append(err)
 	}
